@pytest.fixture(scope="module")
def grunfeld():
    return pd.read_csv(os.path.join(SAMPLE_DIR, "Grunfeld_Panel.csv"))


@pytest.fixture(scope="module")
def grunfeld_unbal(grunfeld):
    """Unbalanced variant with internal gaps (the rule used for the Stata runs)."""
    code = pd.factorize(grunfeld.firm, sort=True)[0]
    return grunfeld[~((grunfeld.year * 7 + code * 3) % 11 == 0)].reset_index(drop=True)


@pytest.fixture(scope="module")
def welfare():
    return pd.read_csv(os.path.join(SAMPLE_DIR, "Dynamic_Panel_Welfare.csv"))


def _coefs(r, extra=("time_effects",)):
    rows = {x["var"].replace("D.", ""): x for x in r.get_table("coef").rows}
    for t in extra:
        if r.get_table(t) is not None:
            rows.update({x["var"]: x for x in r.get_table(t).rows})
    return rows


def _summary(r):
    return {x["metric"]: x["val"] for x in r.get_table("summary").rows}


def _model_test(r):
    s = _summary(r)
    v = [val for k, val in s.items() if k.startswith("F(") or k.startswith("Wald")]
    return v[0] if v else None


SPEC = {  # Stata label suffix -> (modelType, covType, extra options)
    "fe_conv": ("fixed", "unadjusted", {}), "fe_rob": ("fixed", "robust", {}),
    "tw_conv": ("twoway", "unadjusted", {}), "tw_rob": ("twoway", "robust", {}),
    "re_conv": ("random", "unadjusted", {}), "re_rob": ("random", "robust", {}),
    "re_sa": ("random", "unadjusted", {"re_method": "sa"}),
    "be": ("between", "unadjusted", {}), "be_wls": ("between", "unadjusted", {"be_wls": True}),
    "fd_conv": ("fd", "unadjusted", {}), "fd_rob": ("fd", "robust", {}), "fd_cl": ("fd", "clustered", {}),
    "po_conv": ("pooled", "unadjusted", {}), "po_rob": ("pooled", "robust", {}), "po_cl": ("pooled", "clustered", {}),
    "pa_exc": ("pa", "unadjusted", {}), "pa_exc_rob": ("pa", "robust", {}), "pa_ind": ("pa", "unadjusted", {"pa_corr": "independent"}),
    "pa_ar1": ("pa", "unadjusted", {"pa_corr": "ar1"}),
    "fe_dk2": ("fixed", "dk", {"dk_lags": 2}), "fe_dkdef": ("fixed", "dk", {"dk_lags": 18}), "tw_dk2": ("twoway", "dk", {"dk_lags": 2}),
}
SUMMARY_KEYS = {"R² 집단 내 (within)": "r2_w", "R² 집단 간 (between)": "r2_b", "R² 전체 (overall)": "r2_o", "sigma_u": "sigma_u",
                "sigma_e": "sigma_e", "rho (u_i 분산 비중)": "rho", "corr(u_i, Xb)": "corr", "R²": "r2", "수정 R²": "r2_a",
                "Root MSE": "rmse", "척도 모수 (scale)": "phi", "sd(u_i + avg(e_i.))": "rmse"}
CASES = [(d, k) for d in ("bal", "unbal") for k in SPEC if f"{d}_{k}" in STATA_XTREG]


# ----------------------------------------------------------------------------- xtreg family vs Stata 19.5
@pytest.mark.parametrize("data,key", CASES, ids=[f"{d}_{k}" for d, k in CASES])
def test_xtreg_family_matches_stata(data, key, grunfeld, grunfeld_unbal):
    df = grunfeld if data == "bal" else grunfeld_unbal
    mt, ct, kw = SPEC[key]
    r = PanelAnalysis(df, "firm", "year", "invest", ["value", "capital"], model_type=mt, cov_type=ct, hausman=False,
                      plot_trends=False, **kw)
    ref = STATA_XTREG[f"{data}_{key}"]
    rows = _coefs(r)
    tol_b, tol_se = (1e-5, 1e-4) if mt == "pa" else (1e-8, 1e-7)      # Stata xtgee stops at tolerance 1e-6
    for nm, (b, se) in ref["coef"].items():
        row = rows["Intercept" if nm == "_cons" else nm.replace("D.", "")]
        assert row["b"] == pytest.approx(b, rel=tol_b, abs=1e-10), nm
        assert row["se"] == pytest.approx(se, rel=tol_se), nm
    summ = _summary(r)
    for lab, sk in SUMMARY_KEYS.items():
        if lab in summ and sk in ref["stat"] and summ[lab] is not None:
            assert summ[lab] == pytest.approx(ref["stat"][sk], rel=1e-5 if mt == "pa" else 1e-8, abs=1e-12), lab
    stata_test = ref["stat"].get("F", ref["stat"].get("chi2"))
    ours = _model_test(r)
    if stata_test is None:
        assert ours is None            # Stata does not report F when the cluster VCE has rank < k
    else:
        assert ours == pytest.approx(stata_test, rel=1e-4 if mt == "pa" else 1e-7)
    if mt == "random" and "theta" in ref["stat"]:
        vt = {x["item"]: x["val"] for x in r.get_table("variance").rows}
        assert vt["theta"] == pytest.approx(ref["stat"]["theta"], rel=1e-9)


def test_unbalanced_theta_percentiles_follow_stata(grunfeld_unbal):
    r = PanelAnalysis(grunfeld_unbal, "firm", "year", "invest", ["value", "capital"], model_type="random", hausman=False, plot_trends=False)
    vt = {x["item"]: x["val"] for x in r.get_table("variance").rows}
    st = STATA_XTREG["unbal_re_conv"]["stat"]
    for lab, key in (("theta 최소", "thta_min"), ("theta 5%", "thta_5"), ("theta 중앙값", "thta_50"), ("theta 95%", "thta_95"), ("theta 최대", "thta_max")):
        assert vt[lab] == pytest.approx(st[key], rel=1e-9), lab


@pytest.mark.parametrize("data", ["bal", "unbal"])
def test_panel_diagnostics_match_stata(data, grunfeld, grunfeld_unbal):
    df = grunfeld if data == "bal" else grunfeld_unbal
    r = PanelAnalysis(df, "firm", "year", "invest", ["value", "capital"], model_type="fixed", hausman=True, bp_test=True,
                      serial_test=True, cd_test=True, het_test=True, plot_trends=False)
    S = STATA_XTREG
    h = r.get_table("hausman").rows[0]
    assert h["chi2"] == pytest.approx(S[f"{data}_hausman"]["stat"]["chi2"], rel=1e-8) and h["df"] == S[f"{data}_hausman"]["stat"]["df"]
    b = r.get_table("bp_lm").rows[0]
    assert b["chi2"] == pytest.approx(S[f"{data}_xttest0"]["stat"]["chi2"], rel=1e-9)   # r(lm)
    assert b["p"] == pytest.approx(S[f"{data}_xttest0"]["stat"]["p"], rel=1e-6)
    s = r.get_table("serial").rows[0]
    assert s["F"] == pytest.approx(S[f"{data}_xtserial"]["stat"]["F"], rel=1e-9) and s["df2"] == S[f"{data}_xtserial"]["stat"]["df_r"]
    c = r.get_table("cd").rows[0]
    assert c["cd"] == pytest.approx(S[f"{data}_xtcsd_fe"]["stat"]["cd"], rel=1e-9)
    assert c["abs"] == pytest.approx(S[f"{data}_xtcsd_fe"]["stat"]["abs"], rel=1e-9)
    w = r.get_table("het").rows[0]
    assert w["chi2"] == pytest.approx(S[f"{data}_xttest3"]["stat"]["chi2"], rel=1e-8)
    rr = PanelAnalysis(df, "firm", "year", "invest", ["value", "capital"], model_type="random", hausman=False, cd_test=True, plot_trends=False)
    assert rr.get_table("cd").rows[0]["cd"] == pytest.approx(S[f"{data}_xtcsd_re"]["stat"]["cd"], rel=1e-9)


def test_twoway_hausman_matches_stata(grunfeld):
    r = PanelAnalysis(grunfeld, "firm", "year", "invest", ["value", "capital"], model_type="twoway", hausman=True, plot_trends=False)
    h = r.get_table("hausman").rows[0]
    assert h["chi2"] == pytest.approx(STATA_XTREG["bal_hausman_tw"]["stat"]["chi2"], rel=1e-6)
    assert h["df"] == STATA_XTREG["bal_hausman_tw"]["stat"]["df"]


