@pytest.mark.parametrize("key", list(WELFARE_SPEC))
def test_welfare_sample_matches_stata(key, welfare):
    mt, ct, kw = WELFARE_SPEC[key]
    r = PanelAnalysis(welfare, "지역코드", "연도", "복지지출", ["고령인구비율", "재정자립도", "실업률"], model_type=mt, cov_type=ct,
                      hausman=False, plot_trends=False, **kw)
    ref = STATA_XTREG_DW[key]
    rows = _coefs(r)
    tol_b, tol_se = (1e-5, 1e-4) if mt == "pa" else (1e-8, 1e-7)
    for nm, (b, se) in ref["coef"].items():
        row = rows["Intercept" if nm == "_cons" else nm.replace("D.", "")]
        assert row["b"] == pytest.approx(b, rel=tol_b, abs=1e-10), nm
        assert row["se"] == pytest.approx(se, rel=tol_se), nm
    st = ref["stat"].get("F", ref["stat"].get("chi2"))
    assert _model_test(r) == pytest.approx(st, rel=1e-4 if mt == "pa" else 1e-7)
    if "R12" in ref["stat"]:
        assert float(r.fit.stats["alpha"]) == pytest.approx(ref["stat"]["R12"], rel=1e-5)


