# ----------------------------------------------------------------------------- panel behaviour
def test_backward_compatible_panel_api(grunfeld):
    for m_type in ("fixed", "twoway", "random", "pooled"):
        r = ost.panel(grunfeld, entity_col="firm", time_col="year", dep="invest", covs=["value", "capital"], model_type=m_type,
                      hausman=(m_type == "fixed"))
        assert r.get_table("coef").kind == "coefficients" and r.model_stats["N"] == 220
    r = dispatch_analysis("panel", grunfeld, {"entity": "firm", "time": "year", "dep": "invest", "covs": ["value", "capital"],
                                              "modelType": "fe", "covType": "cluster"})
    assert r.options["modelType"] == "fixed" and r.options["covType"] == "clustered"
    assert "Hausman Specification Test" in r.get_table("hausman").title
    assert dispatch_analysis("xtreg", grunfeld, {"entity": "firm", "time": "year", "dep": "invest", "covs": ["value"]}).name == "panel"


def test_invalid_options_and_columns_raise(grunfeld):
    with pytest.raises(ValueError, match="가능"):
        PanelAnalysis(grunfeld, "firm", "year", "invest", ["value"], model_type="mle")
    with pytest.raises(ValueError, match="가능"):
        PanelAnalysis(grunfeld, "firm", "year", "invest", ["value"], cov_type="hc3")
    with pytest.raises(ValueError, match="없는 변수"):
        PanelAnalysis(grunfeld, "firm", "year", "invest", ["valu"])
    with pytest.raises(ValueError, match="중복"):
        PanelAnalysis(pd.concat([grunfeld, grunfeld.head(2)]), "firm", "year", "invest", ["value"])
    with pytest.raises(ValueError, match="nested|포함되지"):
        g2 = grunfeld.assign(cl=np.arange(len(grunfeld)) % 3)
        PanelAnalysis(g2, "firm", "year", "invest", ["value"], cov_type="clustered", cluster="cl")


