# ----------------------------------------------------------------------------- dynamic panel GMM vs Stata 19.5
Y, A, F, U = "복지지출", "고령인구비율", "재정자립도", "실업률"
GMM_SPEC = {
    "dw_d1g": dict(exog=[A], pre=[F], endog=[U]),
    "dw_d1r": dict(exog=[A], pre=[F], endog=[U], vce="robust"),
    "dw_d2g": dict(exog=[A], pre=[F], endog=[U], twostep=True),
    "dw_d2r": dict(exog=[A], pre=[F], endog=[U], twostep=True, vce="robust"),
    "dw_d2r_td": dict(exog=[A], pre=[F], endog=[U], twostep=True, vce="robust", time_dummies=True),
    "dw_lag2": dict(exog=[A], lags=2, maxldep=3, pre=[{"vars": [F], "lags": 1, "maxlags": 2}], constant=False, vce="robust"),
    "dw_s1g": dict(exog=[A], pre=[F], endog=[U], method="system"),
    "dw_s1r": dict(exog=[A], pre=[F], endog=[U], method="system", vce="robust"),
    "dw_s2g": dict(exog=[A], pre=[F], endog=[U], method="system", twostep=True),
    "dw_s2r": dict(exog=[A], pre=[F], endog=[U], method="system", twostep=True, vce="robust"),
    "dw_s2r_max": dict(exog=[A], pre=[F], endog=[U], method="system", twostep=True, vce="robust", maxldep=2, maxlags=2),
}


def _gmm_name(nm):
    if nm == "_cons":
        return "Intercept"
    m = re.fullmatch(r"yd(\d+)", nm)
    if m:
        return f"{2013 + int(m.group(1))}.연도"
    m = re.fullmatch(r"L(\d*)\.(.+)", nm)
    return f"L{m.group(1) or 1}.{m.group(2)}" if m else nm


def _check_gmm(r, ref, check_se=True, dummies=True):
    rows = {x["var"]: x for x in r.get_table("coef").rows}
    for nm, (b, se) in ref["coef"].items():
        if nm.startswith("o.") or (b == 0 and se == 0) or (not dummies and nm.startswith("yd")):
            continue
        row = rows[_gmm_name(nm)]
        assert row["b"] == pytest.approx(b, rel=1e-6, abs=1e-9), nm
        if check_se:
            assert row["se"] == pytest.approx(se, rel=1e-6), nm
    summ = _summary(r)
    st = ref["stat"]
    assert summ["관측치 수 (N)"] == st["N"] and summ["집단 수"] == st["N_g"] and summ["도구변수 수"] == st["zrank"]
    return summ, st


@pytest.mark.parametrize("key", list(GMM_SPEC))
def test_dynamic_gmm_matches_stata(key, welfare):
    kw = GMM_SPEC[key]
    r = DynamicPanelGMM(welfare, "지역코드", "연도", Y, **kw)
    ref = STATA_GMM_DW[key]
    summ, st = _check_gmm(r, ref, dummies=not kw.get("time_dummies"))
    assert _model_test(r) == pytest.approx(st["chi2"], rel=1e-7)
    ar = {x["order"]: x["z"] for x in r.get_table("ar").rows}
    for m in (1, 2):
        if f"arm{m}" in st:
            assert ar[m] == pytest.approx(st[f"arm{m}"], rel=1e-6)
        else:
            assert ar[m] is None          # Stata: one-step system / constant-in-levels GMM VCE -> not computed
    if "sargan" in st:                    # e(sargan): one-step Sargan, two-step = Hansen J with the two-step weights
        ov = {x["test"][:6]: x["chi2"] for x in r.get_table("overid").rows}
        assert ov["Hansen" if kw.get("twostep") else "Sargan"] == pytest.approx(st["sargan"], rel=1e-7)


def test_system_gmm_time_dummies_match_stata_without_redundant_dummy(welfare):
    """Stata keeps the instrument of the omitted (collinear) dummy, which changes its two-step WC-robust VCE;
    with that dummy left out (Stata run 's2r_drop2') Stata and OpenStat agree."""
    r = DynamicPanelGMM(welfare, "지역코드", "연도", Y, exog=[A], pre=[F], endog=[U], method="system", twostep=True,
                        vce="robust", time_dummies=True)
    _check_gmm(r, STATA_GMM_TD["s2r_drop2"])
    _check_gmm(r, STATA_GMM_DW["dw_s2r_td"], check_se=False)             # point estimates equal either way
    for lab, kw in (("s1r_drop2", dict(vce="robust")), ("s2g_drop2", dict(twostep=True)), ("d2r_drop2", dict(twostep=True, vce="robust"))):
        meth = "difference" if lab.startswith("d") else "system"
        r = DynamicPanelGMM(welfare, "지역코드", "연도", Y, exog=[A], pre=[F], endog=[U], method=meth, time_dummies=True, **kw)
        _check_gmm(r, STATA_GMM_TD[lab])


@pytest.mark.parametrize("key", ["d1r_col", "d2r_col", "d2r"])
def test_collapse_matches_r_pgmm(key, welfare):
    """xtabond has no collapse: checked against R plm::pgmm (secondary reference) with the matched specification."""
    kw = {"d1r_col": dict(collapse=True), "d2r_col": dict(collapse=True, twostep=True), "d2r": dict(twostep=True)}[key]
    r = DynamicPanelGMM(welfare, "지역코드", "연도", Y, exog=[A], pre=[F], endog=[U], constant=False, vce="robust", **kw)
    ref = R_PGMM_DW[key]
    rows = {x["var"]: x for x in r.get_table("coef").rows}
    for nm, b, se in zip(["L1.복지지출", A, F, U], ref["b"], ref["se"]):
        assert rows[nm]["b"] == pytest.approx(b, rel=1e-8) and rows[nm]["se"] == pytest.approx(se, rel=1e-7), nm
    ov = {x["test"][:6]: x["chi2"] for x in r.get_table("overid").rows}
    assert ov["Hansen"] == pytest.approx(ref["J"], rel=1e-8)
    ar = [x["z"] for x in r.get_table("ar").rows]
    assert ar[0] == pytest.approx(ref["ar1"], rel=1e-7) and ar[1] == pytest.approx(ref["ar2"], rel=1e-7)


def test_dynamic_lags_follow_time_variable_not_row_order(welfare):
    shuffled = welfare.sample(frac=1.0, random_state=3)
    a = DynamicPanelGMM(welfare, "지역코드", "연도", Y, exog=[A], vce="robust")
    b = DynamicPanelGMM(shuffled, "지역코드", "연도", Y, exog=[A], vce="robust")
    assert [x["b"] for x in a.get_table("coef").rows] == pytest.approx([x["b"] for x in b.get_table("coef").rows], rel=1e-12)
    gap = welfare[~((welfare["연도"] == 2018) & (welfare["지역코드"] == "R001"))]
    c = DynamicPanelGMM(gap, "지역코드", "연도", Y, exog=[A], vce="robust")
    # R001 loses 2018 and the differenced equations of 2018 and 2019 (lag gap) -> 3 fewer differenced rows
    assert _summary(a)["관측치 수 (N)"] - _summary(c)["관측치 수 (N)"] == 3


def test_dynamic_option_semantics_and_errors(welfare):
    r = DynamicPanelGMM(welfare, "지역코드", "연도", Y, exog=[A], pre=[F], endog=[U], method="system", maxldep=2, maxlags=2)
    specs = [x["spec"] for x in r.get_table("instruments").rows]
    assert "L(2/3).복지지출" in specs and "L(1/2).재정자립도" in specs and "L(2/2).실업률" in specs   # Stata footer
    with pytest.raises(ValueError, match="가능"):
        DynamicPanelGMM(welfare, "지역코드", "연도", Y, exog=[A], method="ols")
    with pytest.raises(ValueError, match="없는 변수"):
        DynamicPanelGMM(welfare, "지역코드", "연도", Y, exog=["고령인구"])
    with pytest.raises(ValueError, match="중복"):
        DynamicPanelGMM(welfare, "지역코드", "연도", Y, exog=[A], pre=[A])
    assert parse_terms("L(0/2).(k ys) w L.z") == [("k", 0), ("k", 1), ("k", 2), ("ys", 0), ("ys", 1), ("ys", 2), ("w", 0), ("z", 1)]
    d = dispatch_analysis("xtdpdsys", welfare, {"entity": "지역코드", "time": "연도", "dep": Y, "exog": [A], "method": "system"})
    assert d.name == "dynPanel" and d.get_table("coef").kind == "coefficients" and d.model_stats["Groups"] == 200


# ----------------------------------------------------------------------------- Stata command input and code export
def test_transpile_rules():
    t = panel_transpile("xtreg invest value capital, fe vce(cluster region)")
    assert "modelType='fixed'" in t and "covType='clustered'" in t and "cluster='region'" in t
    assert "modelType='random'" in panel_transpile("xtreg y x1 x2")                    # Stata default = re
    assert "reMethod='sa'" in panel_transpile("xtreg y x, re sa theta")
    assert "modelType='twoway'" in panel_transpile("xtreg y x i.year, fe vce(robust)")
    assert "paCorr='ar1'" in panel_transpile("xtreg y x, pa corr(ar 1) vce(robust)")
    assert "covType='dk'" in panel_transpile("xtscc y x, fe lag(2)") and "dkLags=2" in panel_transpile("xtscc y x, fe lag(2)")
    assert panel_transpile("xtreg y x, fe nonest").startswith("raise NotImplementedError")
    assert "bpTest=True" in panel_transpile("xttest0") and "hetTest=True" in panel_transpile("xttest3")
    assert panel_transpile("regress y x") is None
    g = dyn_transpile("xtdpdsys 복지지출 고령인구비율, lags(1) pre(재정자립도) endogenous(실업률, lagstruct(1,2)) twostep vce(robust)")
    assert "method='system'" in g and "'lags': 1, 'maxlags': 2" in g and "twostep=True" in g and "vce='robust'" in g
    g = dyn_transpile("xtabond n L(0/1).w L(0/2).(k ys) yr1980 year, lags(2) noconstant")
    assert "exog=['L(0/1).w', 'L(0/2).(k ys)', 'yr1980', 'year']" in g and "constant=False" in g
    assert dyn_transpile("xtabond y x, inst(z)").startswith("raise NotImplementedError")
    assert "artests=3" in dyn_transpile("estat abond, artests(3)")
    assert dyn_transpile("estat sargan").startswith("#")
    for line in (panel_transpile("xtreg y x, re"), dyn_transpile("xtabond y x, lags(2)")):
        compile(line, "<transpiled>", "exec")


def test_code_export():
    p = dict(entity="firm", time="year", dep="invest", covs=["value", "capital"], modelType="twoway", covType="dk", hausman=True)
    do = panel_stata("panel", p)
    assert any(l.startswith("xtreg invest value capital i.year, fe vce(dkraay bartlett") for l in do)
    assert "hausman fe re" in do and any("encode firm" in l for l in do)
    assert any("plm::plm(" in l and 'effect = "twoways"' in l for l in panel_r("panel", p))
    q = dict(entity="지역코드", time="연도", dep=Y, exog=[A], pre=[F], endog=[{"vars": [U], "lags": 1, "maxlags": 2}],
             method="system", twostep=True, vce="robust", timeDummies=True)
    do = dyn_stata("dynPanel", q)
    assert any(l.startswith("xtdpdsys 복지지출 고령인구비율 `_td', lags(1)") and "endogenous(실업률, lagstruct(1, 2))" in l for l in do)
    assert any("tabulate 연도, generate(_yr)" in l for l in do) and "estat abond" in do
    assert any("plm::pgmm(" in l and 'transformation = "ld"' in l for l in dyn_r("dynPanel", q))
    assert panel_stata("linReg", {}) is None and dyn_stata("panel", {}) is None


def test_extension_registration():
    from pyjamovi.analyses import extensions
    extensions.reload()
    assert {"panel", "dynPanel"} <= extensions.ids()
    al = extensions.aliases()
    assert al["xtabond"] == "dynPanel" and al["xtreg"] == "panel"
    assert not {k: v for k, v in extensions.load_errors().items() if k in ("panel_module", "dynamic_panel")}
